def numOfSubsequences(s: str) -> int:
    # existing counts via one left-to-right pass
    l = lc = lct = 0   # subsequences "L", "LC", "LCT"
    c = ct = 0         # subsequences "C", "CT"
    for ch in s:
        if ch == 'L':
            l += 1
        elif ch == 'C':
            lc += l
            c += 1
        elif ch == 'T':
            lct += lc
            ct += c

    # best gap for inserting 'C': (#L before) * (#T after)
    t_after = s.count('T')
    l_before = 0
    best_c = 0
    for ch in s:
        best_c = max(best_c, l_before * t_after)
        if ch == 'L':
            l_before += 1
        elif ch == 'T':
            t_after -= 1
    best_c = max(best_c, l_before * t_after)

    # insert 'L' at front (gain ct), 'T' at end (gain lc), or 'C' at best gap
    return lct + max(ct, lc, best_c)
